class RandomizedCollection {
  private vals: number[] = [];

  insert(val: number): boolean {
    const fresh = !this.vals.includes(val);
    this.vals.push(val);
    return fresh;
  }

  remove(val: number): boolean {
    const i = this.vals.indexOf(val);
    if (i === -1) return false;
    this.vals.splice(i, 1);
    return true;
  }

  getRandom(): number {
    return this.vals[Math.floor(Math.random() * this.vals.length)];
  }
}

