class RandomizedCollection {
  private vals: number[] = [];
  private pos = new Map<number, Set<number>>();

  insert(val: number): boolean {
    let s = this.pos.get(val);
    const fresh = !s || s.size === 0;
    if (!s) { s = new Set(); this.pos.set(val, s); }
    s.add(this.vals.length);
    this.vals.push(val);
    return fresh;
  }

  remove(val: number): boolean {
    const s = this.pos.get(val);
    if (!s || s.size === 0) return false;
    const i = s.values().next().value!;
    s.delete(i);
    const end = this.vals.length - 1, last = this.vals[end];
    this.vals[i] = last;
    const ls = this.pos.get(last)!;
    ls.add(i);    // add first: when i === end these cancel out correctly
    ls.delete(end);
    this.vals.pop();
    return true;
  }

  getRandom(): number {
    return this.vals[Math.floor(Math.random() * this.vals.length)];
  }
}

